"""Re-export the Module 3 XGBoost settlement classifier to XGBoost's NATIVE format.

Why
---
The settlement classifier is a ``CalibratedClassifierCV`` wrapping five
``XGBClassifier`` folds, persisted with ``joblib.dump`` (pickle). Every load
prints XGBoost's advisory:

    "If you are loading a serialized model ... generated by an older version of
     XGBoost, please export the model by calling `Booster.save_model` ..."

That warning fires for *any* pickle-based XGBoost load (the stored config version
here is already the current one), so pinning cannot remove it — only the native
format can.

This script performs NO retraining. It loads the existing artifact once and
copies each fold's booster verbatim via ``Booster.save_model`` (.ubj) plus the
Platt/sigmoid calibration parameters into a JSON sidecar, using the same helper
the trainer uses on every retrain.

Run:  python scripts/reexport_module3.py
"""
import sys
import warnings
from pathlib import Path

import joblib

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

# Loading the legacy pickle once triggers the very advisory we are removing.
warnings.filterwarnings("ignore")

from AIML.outcome_prediction import export_native_classifier  # noqa: E402


def main() -> None:
    models = ROOT / "models"
    src = models / "settlement_classifier.pkl"
    if not src.exists():
        raise SystemExit(f"missing source artifact: {src}")

    clf = joblib.load(src)
    sidecar = export_native_classifier(clf, models)
    print(f"[re-export] native sidecar written: {sidecar}")
    print(f"[re-export] {len(clf.calibrated_classifiers_)} fold(s) exported")


if __name__ == "__main__":
    main()
